const $=(q)=>document.querySelector(q);
const state={stories:[],filter:'all',query:'',limit:9,saved:new Set(JSON.parse(localStorage.getItem('hackon-saved')||'[]'))};
const api={hn:'https://hn.algolia.com/api/v1/search_by_date?tags=front_page&hitsPerPage=36',dev:'https://dev.to/api/articles?top=1&per_page=24'};
const clean=(html)=>{const el=document.createElement('div');el.innerHTML=html||'';return(el.textContent||'').trim()};
const safeUrl=(value)=>{try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:'#'}catch{return '#'}};
const dateText=(date)=>{const hours=(Date.now()-new Date(date).getTime())/3600000;if(!Number.isFinite(hours))return 'RECENT';if(hours<1)return 'JUST NOW';if(hours<24)return `${Math.max(1,Math.floor(hours))}H AGO`;return `${Math.floor(hours/24)}D AGO`};
function category(text){const t=text.toLowerCase();if(/\b(ai|artificial intelligence|llm|model|openai|anthropic|claude|machine learning|agent|gpt)\b/.test(t))return 'ai';if(/\b(security|vulnerab|cve|hack|breach|privacy|malware|exploit|cyber)\b/.test(t))return 'security';if(/\b(open.source|github|linux|oss|apache|rust foundation)\b/.test(t))return 'open-source';return 'development'}
function fromHN(x){const title=clean(x.title||x.story_title);if(!title)return null;const url=safeUrl(x.url||x.story_url||`https://news.ycombinator.com/item?id=${x.objectID}`);return{id:`hn-${x.objectID}`,title,url,source:'HACKER NEWS',date:x.created_at,description:`${x.points||0} points · ${x.num_comments||0} comments in the developer community.`,category:category(title),score:x.points||0}}
function fromDev(x){if(!x.title||!x.url)return null;return{id:`dev-${x.id}`,title:x.title,url:safeUrl(x.url),source:'DEV COMMUNITY',date:x.published_at||x.created_at,description:clean(x.description),category:category(`${x.title} ${(x.tag_list||[]).join(' ')}`),score:x.positive_reactions_count||0}}
const escapeHtml=(str)=>String(str).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function visibleStories(){return state.stories.filter(s=>(state.filter==='all'||(state.filter==='saved'?state.saved.has(s.id):s.category===state.filter))&&(!state.query||`${s.title} ${s.description} ${s.source}`.toLowerCase().includes(state.query)))}
function render(){const list=visibleStories();const shown=list.slice(0,state.limit);$('#story-count').textContent=`${list.length} ${list.length===1?'STORY':'STORIES'}`;$('#saved-count').textContent=state.saved.size;$('#load-more').hidden=list.length<=state.limit;$('#stories').innerHTML=shown.length?shown.map(s=>`<article class="story-card"><div class="story-top"><span class="story-source"><i class="source-dot"></i>${escapeHtml(s.source)}</span><time datetime="${escapeHtml(s.date||'')}">${dateText(s.date)}</time></div><h3><a href="${escapeHtml(s.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(s.title)}</a></h3><p>${escapeHtml(s.description||'Open this story at its original source.')}</p><div class="story-bottom"><span class="story-tag">${escapeHtml(s.category.replace('-',' ').toUpperCase())}</span><span class="story-actions"><button class="save-button ${state.saved.has(s.id)?'saved':''}" data-save="${escapeHtml(s.id)}" type="button" aria-label="${state.saved.has(s.id)?'Remove saved story':'Save story'}" title="${state.saved.has(s.id)?'Remove saved story':'Save story'}">${state.saved.has(s.id)?'★':'☆'}</button><a class="story-link" href="${escapeHtml(s.url)}" target="_blank" rel="noopener noreferrer" aria-label="Read ${escapeHtml(s.title)} at source">↗</a></span></div></article>`).join(''):`<div class="empty"><h3>No stories found.</h3><p>${state.filter==='saved'?'Save stories with the star button to keep them here.':'Try another topic or search term.'}</p></div>`}
async function loadStories(){const status=$('#feed-status');status.textContent='Connecting to live sources…';$('#refresh').disabled=true;const results=await Promise.allSettled([fetch(api.hn,{headers:{Accept:'application/json'}}).then(r=>{if(!r.ok)throw Error('HN unavailable');return r.json()}),fetch(api.dev,{headers:{Accept:'application/json'}}).then(r=>{if(!r.ok)throw Error('DEV unavailable');return r.json()})]);const hn=(results[0].status==='fulfilled'?(results[0].value.hits||[]).map(fromHN):[]).filter(Boolean).filter(s=>s.url!=='#');const dev=(results[1].status==='fulfilled'?(results[1].value||[]).map(fromDev):[]).filter(Boolean).filter(s=>s.url!=='#');state.stories=[];for(let i=0;i<Math.max(hn.length/2,dev.length);i++){state.stories.push(...hn.slice(i*2,i*2+2));if(dev[i])state.stories.push(dev[i])}const live=results.filter(r=>r.status==='fulfilled').length;status.textContent=live?`LIVE FROM ${live===2?'HACKER NEWS + DEV COMMUNITY':results[0].status==='fulfilled'?'HACKER NEWS':'DEV COMMUNITY'} · UPDATED ${new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}`:'Live sources are unavailable right now. Refresh to retry.';$('#refresh').disabled=false;render()}
$('#menu-toggle').addEventListener('click',()=>{const open=$('#main-nav').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open));$('#menu-toggle').setAttribute('aria-label',open?'Close navigation':'Open navigation')});
document.querySelectorAll('#main-nav a').forEach(a=>a.addEventListener('click',()=>{$('#main-nav').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false')}));
document.querySelectorAll('.filter').forEach(button=>button.addEventListener('click',()=>{document.querySelector('.filter.active')?.classList.remove('active');button.classList.add('active');state.filter=button.dataset.filter;state.limit=9;render()}));
document.querySelectorAll('[data-topic]').forEach(link=>link.addEventListener('click',()=>{const button=document.querySelector(`.filter[data-filter="${link.dataset.topic}"]`);button?.click()}));
$('#search').addEventListener('input',e=>{state.query=e.target.value.trim().toLowerCase();state.limit=9;render()});
$('#refresh').addEventListener('click',loadStories);$('#load-more').addEventListener('click',()=>{state.limit+=9;render()});
$('#stories').addEventListener('click',e=>{const button=e.target.closest('[data-save]');if(!button)return;const id=button.dataset.save;state.saved.has(id)?state.saved.delete(id):state.saved.add(id);localStorage.setItem('hackon-saved',JSON.stringify([...state.saved]));render()});
$('#year').textContent=new Date().getFullYear();$('#hero-clock').textContent=`${new Date().toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'}).toUpperCase()} / LIVE, EVERY DAY`;
loadStories();
